function i(){const t=document.querySelectorAll("#related-posts, .related-posts");if(!t.length)return;const s=e=>{window.dispatchEvent(new CustomEvent("psyui:load-related-posts",{detail:{container:e}}))};if("IntersectionObserver"in window){const e=new IntersectionObserver((o,n)=>{o.forEach(r=>{r.isIntersecting&&(s(r.target),n.unobserve(r.target))})},{rootMargin:"200px"});t.forEach(o=>e.observe(o))}else t.forEach(e=>s(e))}export{i as initRelatedPosts};
